void NodeTreeInterfaceSocketObject_default_value_set(PointerRNA *ptr, PointerRNA value, ReportList *reports)
{
    bNodeSocketValueObject *data = (bNodeSocketValueObject *)(((bNodeTreeInterfaceSocket *)ptr->data)->socket_data);
    if (value.data && ptr->owner_id && value.owner_id && !BKE_id_can_use_id(*ptr->owner_id, *value.owner_id)) {
      return;
    }

    if (data->value) {
        id_us_min((ID *)data->value);
    }
    if (value.data) {
        id_us_plus((ID *)value.data);
    }
    *(void **)&data->value = value.data;
}

